def _blocks(s):
    """Yield 3‑char blocks from s."""
    for i in range(0, len(s), 3):
        yield s[i:i+3]

def encode_cyclic(s: str) -> str:
    """Rotate every full 3‑char block left by one."""
    return ''.join(
        block[1:] + block[0] if len(block) == 3 else block
        for block in _blocks(s)
    )

def decode_cyclic(s: str) -> str:
    """Rotate every full 3‑char block right by one."""
    return ''.join(
        block[-1] + block[:-1] if len(block) == 3 else block
        for block in _blocks(s)
    )

# Example usage:
