def count_digit_7(n: int) -> int:
    """
    Counts the total occurrences of the digit '7' in all numbers from 1 to n
    that are divisible by 11 or 13.
    """
    if n < 1:
        return 0

    # Memoization for the digit count function
    memo = {}

    def count_7_in_number(num: int) -> int:
        """Returns the count of digit '7' in the decimal representation of num."""
        if num in memo:
            return memo[num]

        count = 0
        temp = num
        while temp > 0:
            if temp % 10 == 7:
                count += 1
            temp //= 10

        memo[num] = count
        return count

    # Functional approach using sum and generator expression
    # We iterate through numbers and check divisibility
    return sum(
        count_7_in_number(i) 
        for i in range(1, n + 1) 
        if i % 11 == 0 or i % 13 == 0
